{"content": "use super::error::{ConfigError, ConfigResult};
use super::models::*;
use super::validation::ConfigValidator;
use chrono::{DateTime, Utc};
use serde_json;
use std::fs;
use std::path::{Path, PathBuf};

pub struct ConfigLoader {
    config_path: PathBuf,
    backup_dir: PathBuf,
}

impl ConfigLoader {
    pub fn new<P: AsRef<Path>>(config_path: P) -> Self {
        let config_path = config_path.as_ref().to_path_buf();
        let backup_dir = PathBuf::from("config_backup");

        Self {
            config_path,
            backup_dir,
        }
    }

    pub fn with_backup_dir<P: AsRef<Path>, B: AsRef<Path>>(config_path: P, backup_dir: B) -> Self {
        let config_path = config_path.as_ref().to_path_buf();
        let backup_dir = backup_dir.as_ref().to_path_buf();

        Self {
            config_path,
            backup_dir,
        }
    }

    /// Load configuration from file
    pub fn load(&self) -> ConfigResult<AppConfig> {
        if !self.config_path.exists() {
            return Err(ConfigError::FileNotFound {
                path: self.config_path.display().to_string(),
            });
        }

        let content = fs::read_to_string(&self.config_path)?;
        let mut config: AppConfig = serde_json::from_str(&content)?;

        // Set names for sensors, fans, and alarms based on HashMap keys
        self.populate_names(&mut config);

        // Validate the configuration
        config.validate()?;

        Ok(config)
    }

    /// Load configuration with defaults for missing file
    pub fn load_or_default(&self) -> ConfigResult<AppConfig> {
        match self.load() {
            Ok(config) => Ok(config),
            Err(ConfigError::FileNotFound { .. }) => {
                let config = AppConfig::default();
                config.validate()?;
                Ok(config)
            }
            Err(e) => Err(e),
        }
    }

    /// Save configuration to file
    pub fn save(&self, config: &AppConfig) -> ConfigResult<()> {
        // Validate before saving
        config.validate()?;

        // Create parent directory if it doesn't exist
        if let Some(parent) = self.config_path.parent() {
            fs::create_dir_all(parent)?;
        }

        let content = serde_json::to_string_pretty(config)?;
        fs::write(&self.config_path, content)?;

        Ok(())
    }

    /// Update configuration with backup
    pub fn update(&self, config: &AppConfig) -> ConfigResult<()> {
        // Backup current config if it exists
        if self.config_path.exists() {
            self.backup_current()?;
        }

        // Save new config
        self.save(config)
    }

    /// Update partial configuration (for API updates)
    pub fn update_partial(&self, updates: serde_json::Value) -> ConfigResult<AppConfig> {
        // Load current config
        let mut current = self.load_or_default()?;

        // Apply updates
        let current_json = serde_json::to_value(&current)?;
        let merged = merge_json(current_json, updates);

        // Parse back to AppConfig
        let updated: AppConfig = serde_json::from_value(merged)?;

        // Set names for sensors, fans, and alarms
        let mut final_config = updated;
        self.populate_names(&mut final_config);

        // Update with backup
        self.update(&final_config)?;

        Ok(final_config)
    }

    /// Backup current configuration
    pub fn backup_current(&self) -> ConfigResult<String> {
        if !self.config_path.exists() {
            return Err(ConfigError::BackupFailed {
                message: "No configuration file to backup".to_string(),
            });
        }

        // Create backup directory
        fs::create_dir_all(&self.backup_dir)?;

        // Generate backup filename with timestamp
        let timestamp = Utc::now().format("%Y%m%d_%H%M%S");
        let backup_filename = format!("config_backup_{}.json", timestamp);
        let backup_path = self.backup_dir.join(&backup_filename);

        // Copy current config to backup
        fs::copy(&self.config_path, &backup_path)?;

        Ok(backup_filename)
    }

    /// List available backups
    pub fn list_backups(&self) -> ConfigResult<Vec<BackupInfo>> {
        if !self.backup_dir.exists() {
            return Ok(Vec::new());
        }

        let mut backups = Vec::new();

        for entry in fs::read_dir(&self.backup_dir)? {
            let entry = entry?;
            let path = entry.path();

            if path.is_file() && path.extension().map_or(false, |ext| ext == "json") {
                if let Some(filename) = path.file_name().and_then(|n| n.to_str()) {
                    if filename.starts_with("config_backup_") {
                        let metadata = fs::metadata(&path)?;
                        let created = metadata.created()
                            .map(DateTime::<Utc>::from)
                            .unwrap_or_else(|_| Utc::now());

                        backups.push(BackupInfo {
                            filename: filename.to_string(),
                            path: path.clone(),
                            created,
                            size: metadata.len(),
                        });
                    }
                }
            }
        }

        // Sort by creation time, newest first
        backups.sort_by(|a, b| b.created.cmp(&a.created));

        Ok(backups)
    }

    /// Restore configuration from backup
    pub fn restore_from_backup(&self, backup_filename: &str) -> ConfigResult<AppConfig> {
        let backup_path = self.backup_dir.join(backup_filename);

        if !backup_path.exists() {
            return Err(ConfigError::RestoreFailed {
                message: format!("Backup file '{}' not found", backup_filename),
            });
        }

        // Load and validate backup
        let content = fs::read_to_string(&backup_path)?;
        let mut config: AppConfig = serde_json::from_str(&content)
            .map_err(|e| ConfigError::RestoreFailed {
                message: format!("Invalid backup file format: {}", e),
            })?;

        // Set names for sensors, fans, and alarms
        self.populate_names(&mut config);

        // Validate the backup configuration
        config.validate().map_err(|e| ConfigError::RestoreFailed {
            message: format!("Backup configuration is invalid: {}", e),
        })?;

        // Backup current config before restoring
        if self.config_path.exists() {
            self.backup_current()?;
        }

        // Save restored config
        self.save(&config)?;

        Ok(config)
    }

    /// Apply CLI overrides to configuration
    pub fn apply_cli_overrides(&self, mut config: AppConfig, cli_overrides: &CliOverrides) -> ConfigResult<AppConfig> {
        if let Some(port) = cli_overrides.port {
            config.server.port = port;
        }

        if let Some(ref host) = cli_overrides.host {
            config.server.host = host.clone();
        }

        if let Some(timeout) = cli_overrides.timeout {
            config.server.request_timeout_seconds = timeout;
        }

        if let Some(mock_mode) = cli_overrides.mock_mode {
            config.hardware.mock_mode = mock_mode;
        }

        // Re-validate after applying overrides
        config.validate()?;

        Ok(config)
    }

    /// Set names for hashmap-based configs based on their keys
    fn populate_names(&self, config: &mut AppConfig) {
        for (name, sensor) in config.temp_sensors.iter_mut() {
            sensor.name = name.clone();
        }

        for (name, fan) in config.fans.iter_mut() {
            fan.name = name.clone();
        }

        for (name, alarm) in config.alarms.iter_mut() {
            alarm.name = name.clone();
        }
    }
}

#[derive(Debug, Clone)]
pub struct BackupInfo {
    pub filename: String,
    pub path: PathBuf,
    pub created: DateTime<Utc>,
    pub size: u64,
}

#[derive(Debug, Default)]
pub struct CliOverrides {
    pub port: Option<u16>,
    pub host: Option<String>,
    pub timeout: Option<u64>,
    pub mock_mode: Option<bool>,
}

/// Merge two JSON values, with the second taking precedence
fn merge_json(mut base: serde_json::Value, update: serde_json::Value) -> serde_json::Value {
    match (&mut base, update) {
        (serde_json::Value::Object(base_map), serde_json::Value::Object(update_map)) => {
            for (key, value) in update_map {
                base_map.insert(key, value);
            }
            base
        }
        (_, update) => update,
    }
}

