use clap::Parser;
use rpi_smoker_backend::{
    api::create_router,
    config::{AppConfig, CliOverrides, ConfigLoader},
};
use std::net::SocketAddr;
use std::path::PathBuf;
use tokio::signal;
use tracing::{info, warn};

let args = Cli::parse();

// Load configuration
let loader = ConfigLoader::new(&args.config);
let base_config = loader.load_or_default().map_err(|e| {
    eprintln!("Failed to load configuration: {}", e);
    std::process::exit(1);
}).unwrap();

// Apply CLI overrides
let cli_overrides = create_cli_overrides(&args);
let config = loader.apply_cli_overrides(base_config, &cli_overrides).map_err(|e| {
    eprintln!("Failed to apply CLI overrides: {}", e);
    std::process::exit(1);
}).unwrap();

info!("Configuration loaded from: {}", args.config.display());

// Check if we're on a Raspberry Pi or hardware features are enabled
if !config.hardware.mock_mode {
    #[cfg(all(feature = "rpi-hardware", target_os = "linux"))]
    {
        info!("Hardware features enabled");
        // TODO: Initialize GPIO and sensor interfaces
    }
    #[cfg(not(all(feature = "rpi-hardware", target_os = "linux")))]
    {
        warn!(
            "Hardware features requested but not available on this platform or not compiled in."
        );
        warn!("To enable hardware features: use --features rpi-hardware on Linux");
    }
} else {
    info!("Running in mock mode without hardware features");
}

fn validate_port(port: u16) -> ConfigResult<()> {
    if port < 1024 {
        return Err(ConfigError::ValidationFailed {
            field: "port".to_string(),
            message: "Port must be between 1024 and 65535".to_string(),
        });
    }
    Ok(())
}

fn validate_poll_interval(interval: u64) -> ConfigResult<()> {
    if !(250..=60000).contains(&interval) {
        return Err(ConfigError::ValidationFailed {
            field: "poll_interval_ms".to_string(),
            message: "Poll interval must be between 250ms and 60000ms".to_string(),
        });
    }
    Ok(())
}

fn validate_timeout(timeout: u64) -> ConfigResult<()> {
    if !(1..=3600).contains(&timeout) {
        return Err(ConfigError::ValidationFailed {
            field: "request_timeout_seconds".to_string(),
            message: "Timeout must be between 1 and 3600 seconds".to_string(),
        });
    }
    Ok(())
}

fn validate_frequency(freq: u32) -> ConfigResult<()> {
    if !(1..=100000).contains(&freq) {
        return Err(ConfigError::ValidationFailed {
            field: "frequency_hz".to_string(),
            message: "PWM frequency must be between 1Hz and 100kHz".to_string(),
        });
    }
    Ok(())
}

fn validate_memory_limit(mb: u64) -> ConfigResult<()> {
    if !(10..=4096).contains(&mb) {
        return Err(ConfigError::ValidationFailed {
            field: "max_memory_mb".to_string(),
            message: "Memory limit must be between 10MB and 4GB".to_string(),
        });
    }
    Ok(())
}

