/// Get current configuration
pub async fn get_config(State(state): State<AppState>) -> Result<Json<Value>, (StatusCode, Json<Value>)> {
    let config = state.loader.load_or_default()
        .map_err(|e| (
            StatusCode::INTERNAL_SERVER_ERROR,
            Json(json!({ "error": format!("Failed to load configuration: {e}") }))
        ))?;

    Ok(Json(serde_json::to_value(config).unwrap()))
}

/// Update configuration
pub async fn update_config(
    State(state): State<AppState>,
    Json(updates): Json<Value>
) -> Result<Json<Value>, (StatusCode, Json<Value>)> {
    let updated_config = state.loader.update_partial(updates)
        .map_err(|e| (
            StatusCode::BAD_REQUEST,
            Json(json!({ "error": format!("Failed to update configuration: {e}") }))
        ))?;

    Ok(Json(json!({
        "message": "Configuration updated successfully",
        "config": serde_json::to_value(updated_config).unwrap()
    })))
}

