pub async fn list_config_backups(State(state): State<AppState>) -> Result<Json<Value>, (StatusCode, Json<Value>)> {
    let backups = state.loader.list_backups()
        .map_err(|e| (
            StatusCode::INTERNAL_SERVER_ERROR,
            Json(json!({ "error": format!("Failed to list backups: {e}") }))
        ))?;

    Ok(Json(json!({ "backups": backups })))
}

/// Restore configuration from backup
pub async fn restore_config_backup(
    State(state): State<AppState>,
    Path(backup_filename): Path<String>
) -> Result<Json<Value>, (StatusCode, Json<Value>)> {
    let restored_config = state.loader.restore_from_backup(&backup_filename)
        .map_err(|e| (
