use std::net::SocketAddr;
use std::path::PathBuf;
use tokio::signal;
use tracing::{info, warn};

#[derive(Parser, Debug)]
#[command(name = "rpi-smoker")]
#[command(about = "Raspberry Pi Smoker Controller")]
pub struct Cli {
    #[arg(short, long, default_value = "config.json")]
    pub config: PathBuf,

    #[arg(long)]
    pub port: Option<u16>,

    #[arg(long)]
    pub host: Option<String>,

    #[arg(long)]
    pub timeout: Option<u64>,

    #[arg(long)]
    pub mock_mode: Option<bool>,
}

fn create_cli_overrides(args: &Cli) -> CliOverrides {
    CliOverrides {
        port: args.port,
        host: args.host.clone(),
        timeout: args.timeout,
        mock_mode: args.mock_mode,
    }
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    // Initialize tracing
    tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| "rpi_smoker_backend=debug,tower_http=debug".into()),
        )
        .init();

    let args = Cli::parse();

    // Load configuration
    let loader = ConfigLoader::new(&args.config);
    let base_config = loader.load_or_default().map_err(|e| {
        eprintln!("Failed to load configuration: {e}");
        std::process::exit(1);
    }).unwrap();

    // Apply CLI overrides
    let cli_overrides = create_cli_overrides(&args);
    let config = loader.apply_cli_overrides(base_config, &cli_overrides).map_err(|e| {
        eprintln!("Failed to apply CLI overrides: {e}");
        std::process::exit(1);
    }).unwrap();

    info!("Configuration loaded from: {}", args.config.display());

    // Check if we're on a Raspberry Pi or hardware features are enabled
    if !config.hardware.mock_mode {
        #[cfg(all(feature = "rpi-hardware", target_os = "linux"))]
        {
            info!("Hardware features enabled");
            // TODO: Initialize GPIO and sensor interfaces
        }
        #[cfg(not(all(feature = "rpi-hardware", target_os = "linux")))]
        {
            warn!(
                "Hardware features requested but not available on this platform or not compiled in."
            );
            warn!("To enable hardware features: use --features rpi-hardware on Linux");
        }
    } else {
        info!("Running in mock mode without hardware features");
    }

    let app = create_router(&config);

    let addr = SocketAddr::from(([0, 0, 0, 0], config.server.port));
    info!(
        "Starting server on {}:{}",
        config.server.host, config.server.port
    );
    info!(
        "Health check available at http://{}:{}/api/health",
        config.server.host, config.server.port
    );
    info!("API routes available under /api/*");

    let listener = tokio::net::TcpListener::bind(addr).await?;

    // Run server with graceful shutdown
    axum::serve(listener, app)
        .with_graceful_shutdown(shutdown_signal())
        .await?;

    Ok(())
}

/// Handle graceful shutdown signals
async fn shutdown_signal() {
    let ctrl_c = async {
        signal::ctrl_c()
            .await
            .expect("failed to install Ctrl+C handler");
    };

    #[cfg(unix)]
    let terminate = async {
        signal::unix::signal(signal::unix::SignalKind::terminate())
            .expect("failed to install signal handler")
            .recv()
            .await;
    };

    #[cfg(not(unix))]
    let terminate = std::future::pending::<()>();

    tokio::select! {
        _ = ctrl_c => {
            info!("Received Ctrl+C, starting graceful shutdown");
        },
        _ = terminate => {
            info!("Received SIGTERM, starting graceful shutdown");
        },
    }
}


